import {particleText as text,plainJapanese} from '../particles/ui.js';
import {scenarioGrammarIds,scenarioGrammarLabel} from './data.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const scenarioGrammarLinks=ids=>'<div class="sc-grammar-links" aria-label="相關文法課程">'+ids.map(id=>'<button class="secondary" data-glesson="'+id+'">'+scenarioGrammarLabel(id)+' ↗</button>').join('')+'</div>';
export function scenarioTeaching(l,index,tokenIndex){
  const p=l.points[index]||l.points[0],part=p.parts[tokenIndex]||p.parts[0],form=p.parts.some(t=>t.jp.includes('→'));
  const speech=form?'':'<button class="g-sound" data-action="speak" data-text="'+esc(plainJapanese(p.parts.map(t=>t.jp).join('')+'。'))+'" aria-label="聽這個情境例句">♪</button>';
  return '<div class="grammar sc-teaching"><div class="section-title"><div><h2>把對話裡的文法看清楚</h2><p class="muted">點選重點與詞塊，也能回到相關文法課。</p></div></div><div class="g-example-tabs" role="group" aria-label="切換情境文法重點">'+l.points.map((p,i)=>'<button data-scpoint="'+i+'" aria-pressed="'+(i===index)+'">'+(i+1)+' · '+p.title+'</button>').join('')+'</div><div class="g-token-sentence" lang="ja">'+p.parts.map((t,i)=>'<button class="g-token token-'+i%4+'" data-sctoken="'+i+'" aria-pressed="'+(i===tokenIndex)+'" aria-label="'+esc(plainJapanese(t.jp))+'：'+esc(t.label)+'">'+text(t.jp)+'<small>'+t.label+'</small></button>').join('')+(form?'':'<span>。</span>')+'</div><p class="g-translation">'+p.zh+speech+'</p><div class="g-token-note" role="status"><span class="g-role-label">'+part.label+'</span><strong lang="ja">'+text(part.jp)+'</strong><p>'+part.note+'</p></div><div class="pattern"><span class="eyebrow">這個情境，用這個句型</span><h2 lang="ja">'+text(p.pattern)+'</h2><p>'+p.explain+'</p></div>'+scenarioGrammarLinks(p.refs)+'<p class="g-small-note">本課六題會實際練習這些概念。作答會更新文法概念的複習紀錄；情境課與文法課的完成成績分開保存。</p></div>';
}
export const scenarioCourseTopics=l=>l.kind==='application'?'<p class="sc-topics">應用文法 '+scenarioGrammarIds(l).map(id=>scenarioGrammarLabel(id).split(' · ')[0]).join('、')+' · '+l.questions.length+' 題</p>':'';
export function scenarioCourseList(lessons,progress,icon){
  const applied=lessons.filter(l=>l.kind==='application'),covered=scenarioGrammarIds({questions:applied.flatMap(l=>l.questions)});
  const legacy=lessons.filter(l=>l.kind!=='application'),total=lessons.reduce((n,l)=>n+l.questions.length,0);
  const cards=items=>'<div class="course-list">'+items.map(l=>{const i=lessons.indexOf(l),p=progress[l.id];return '<button class="course-card" data-start="'+l.id+'"><div class="course-cover '+l.color+'"><span class="course-num">LESSON '+String(i+1).padStart(2,'0')+'</span>'+icon(l.icon)+'<span class="course-ja">'+(l.ja||['はじめまして','コーヒー','いくらですか','どこですか','好きです'][i])+'</span></div><div class="course-info"><small>'+l.category+' · '+l.time+' 分鐘</small><h2>'+l.title+'</h2><p>'+l.desc+'</p>'+scenarioCourseTopics(l)+'<div class="course-bottom"><span class="pill">'+(p?.complete?'✓ 已完成':p?'學習中':l.kind==='application'?'文法應用':'初級入門')+'</span>'+(Number.isInteger(p?.best)?'<small>最佳 '+p.best+' / '+l.questions.length+' 題</small>':icon('arrow'))+'</div></div></button>';}).join('')+'</div>';
  return '<section class="sc-overview"><h2>學過的文法，放進真實對話</h2><p>'+legacy.length+' 堂入門情境＋'+applied.length+' 堂文法應用，共 '+total+' 題。應用題涵蓋目前 '+covered.length+' 堂基礎文法，可自由選課。答錯的概念會加入文法複習；情境成績獨立保存。</p><a class="secondary sc-application-link" href="#scenario-application">直接看 '+applied.length+' 堂文法應用 ↓</a><details class="sc-curriculum-map"><summary>回看對應的基礎文法（'+covered.length+' 課）</summary>'+scenarioGrammarLinks(covered)+'</details></section><div class="section-title"><h2>先從一段簡單對話開始</h2><span>5 堂入門情境</span></div>'+cards(lessons.filter(l=>l.kind!=='application'))+'<div class="section-title sc-section-title" id="scenario-application"><h2>把文法用在生活裡</h2><span>8 堂應用 · 每堂 6 題</span></div>'+cards(applied);
}
